create table public.cti_catalogo_equipamentos (codigo text not null, linha_produto text not null, modelo_base text not null, nome_comercial text not null, configuracao text default 'PADRAO'::text not null, compressor text, possui_eletrico boolean default false not null, descricao_tecnica jsonb default '{}'::jsonb not null, template_disponivel boolean default false not null, ativo boolean default true not null, ordem integer default 0 not null, created_at timestamp with time zone default now() not null, updated_at timestamp with time zone default now() not null);
create table public.cti_feira_atendimentos (id uuid default gen_random_uuid() not null, feira_id uuid not null, empresa text not null, cnpj text, visitante text not null, contato text, email text, cidade text, uf text, regiao text default 'A_CONFIRMAR'::text not null, autorizado_destino text, interesse text, observacoes text, status text default 'REGISTRADO'::text not null, moeda text, valor_referencia numeric(16,2), oportunidade_id uuid, criado_por text not null, criado_em timestamp with time zone default now() not null, atualizado_em timestamp with time zone default now() not null);
create table public.cti_feira_itens (id uuid default gen_random_uuid() not null, atendimento_id uuid not null, codigo_produto text, linha_produto text not null, nome_produto text not null, quantidade integer not null, lancamento_feira boolean default false not null, descricao_lancamento text);
create table public.cti_feiras (id uuid default gen_random_uuid() not null, nome text not null, inicio date, fim date, local text, ativo boolean default true not null, criado_em timestamp with time zone default now() not null);
create table public.cti_user_permissions (user_id uuid not null, acesso_portal boolean default false not null, acesso_crm boolean default false not null, dashboard_executivo boolean default false not null, clientes_visualizar boolean default false not null, clientes_editar boolean default false not null, oportunidades_visualizar boolean default false not null, oportunidades_editar boolean default false not null, propostas_visualizar boolean default false not null, propostas_emitir boolean default false not null, pedidos_visualizar boolean default false not null, pedidos_converter boolean default false not null, pedidos_enviar boolean default false not null, financeiro_visualizar boolean default false not null, usuarios_administrar boolean default false not null, configuracoes_administrar boolean default false not null, acesso_total boolean default false not null, created_at timestamp with time zone default now() not null, updated_at timestamp with time zone default now() not null);
create table public.cti_users (id uuid default uuid_generate_v4() not null, auth_id uuid, email text, nome text, empresa text, tipo_usuario text, ativo boolean default true, created_at timestamp without time zone default now(), cargo text, nivel_hierarquico text, empresa_operacional text, codigo_regional text, gestor_direto text, escopo_visualizacao text, funcao text, superior_id uuid, senha_temporaria_criada_em timestamp with time zone, primeiro_acesso_concluido_em timestamp with time zone, gestor_responsavel text, status_acesso text default 'PRIMEIRO_ACESSO_PENDENTE'::text, primeiro_acesso_pendente boolean default true not null, cadastro_completo boolean default false not null, telefone text, departamento text, territorio text, ddds text[] default '{}'::text[] not null, updated_at timestamp with time zone default now() not null);
alter table public.cti_catalogo_equipamentos add constraint cti_catalogo_configuracao_check CHECK (configuracao = ANY (ARRAY['PADRAO'::text, 'ACOPLADO'::text, 'ACOPLADO_E_ELETRICO'::text]));
alter table public.cti_catalogo_equipamentos add constraint cti_catalogo_equipamentos_pkey PRIMARY KEY (codigo);
alter table public.cti_feira_atendimentos add constraint cti_feira_atendimentos_moeda_check CHECK (moeda = ANY (ARRAY['BRL'::text, 'USD'::text]));
alter table public.cti_feira_atendimentos add constraint cti_feira_atendimentos_pkey PRIMARY KEY (id);
alter table public.cti_feira_atendimentos add constraint cti_feira_atendimentos_regiao_check CHECK (regiao = ANY (ARRAY['VIENA'::text, 'OUTRA'::text, 'A_CONFIRMAR'::text]));
alter table public.cti_feira_itens add constraint cti_feira_itens_pkey PRIMARY KEY (id);
alter table public.cti_feira_itens add constraint cti_feira_itens_quantidade_check CHECK (quantidade > 0);
alter table public.cti_feiras add constraint cti_feiras_nome_unique UNIQUE (nome);
alter table public.cti_feiras add constraint cti_feiras_pkey PRIMARY KEY (id);
alter table public.cti_user_permissions add constraint cti_user_permissions_pkey PRIMARY KEY (user_id);
alter table public.cti_users add constraint cti_users_pkey PRIMARY KEY (id);
alter table public.cti_feira_atendimentos add constraint cti_feira_atendimentos_feira_id_fkey FOREIGN KEY (feira_id) REFERENCES cti_feiras(id);
alter table public.cti_feira_itens add constraint cti_feira_itens_atendimento_id_fkey FOREIGN KEY (atendimento_id) REFERENCES cti_feira_atendimentos(id) ON DELETE CASCADE;
alter table public.cti_user_permissions add constraint cti_user_permissions_user_id_fkey FOREIGN KEY (user_id) REFERENCES cti_users(id) ON DELETE CASCADE;
alter table public.cti_users add constraint cti_users_auth_id_fkey FOREIGN KEY (auth_id) REFERENCES auth.users(id);
alter table public.cti_users add constraint cti_users_superior_id_fkey FOREIGN KEY (superior_id) REFERENCES cti_users(id) ON DELETE SET NULL;
CREATE UNIQUE INDEX ux_cti_users_email_normalizado ON public.cti_users USING btree (lower(TRIM(BOTH FROM email))) WHERE ((email IS NOT NULL) AND (TRIM(BOTH FROM email) <> ''::text));
CREATE INDEX idx_cti_feira_itens_atendimento ON public.cti_feira_itens USING btree (atendimento_id);
CREATE INDEX ix_cti_users_tipo_usuario ON public.cti_users USING btree (tipo_usuario);
CREATE INDEX cti_users_superior_id_idx ON public.cti_users USING btree (superior_id);
CREATE INDEX ix_cti_users_territorio ON public.cti_users USING btree (territorio);
CREATE INDEX idx_cti_feira_atendimentos_feira ON public.cti_feira_atendimentos USING btree (feira_id, criado_em DESC);
CREATE UNIQUE INDEX ux_cti_users_auth_id ON public.cti_users USING btree (auth_id) WHERE (auth_id IS NOT NULL);
CREATE INDEX idx_cti_feira_itens_lancamentos ON public.cti_feira_itens USING btree (lancamento_feira) WHERE (lancamento_feira = true);
alter table public.cti_users enable row level security;
